mapper.select:
SELECT user_plant_id, ori_name, sys_name, url, hash FROM ( -- 대표 이미지 SELECT user_plant_id, ori_name, sys_name, url, hash FROM my_plant_image WHERE hash = #{hash}
UNION ALL
-- 히스토리 이미지 SELECT user_plant_id, ori_name, sys_name, url, hash FROM my_plant_image_history WHERE hash = #{hash}
UNION ALL
-- 다이어리 이미지 SELECT dd.user_plant_id, d.ori_name, d.sys_name, d.url, d.hash FROM my_plant_diary_image d JOIN my_plant_diary dd ON d.diary_id = dd.diary_id WHERE d.hash = #{hash} ) WHERE ROWNUM = 1

SELECT COUNT(*)
FROM (
         SELECT hash FROM my_plant_image WHERE hash = #{hash}
         UNION ALL
         SELECT hash FROM my_plant_image_history WHERE hash = #{hash}
         UNION ALL
         SELECT hash FROM my_plant_diary_image WHERE hash = #{hash}
     )
